<script setup>
import {ref,computed,onMounted,reactive,watch} from 'vue'
const props=defineProps({api:Function})
const endpoints=ref([]),keys=ref([]),selected=ref(null),search=ref(''),error=ref(''),notice=ref(''),busy=ref(false),token=ref(''),newToken=ref(''),mode=ref('key'),body=ref('{}'),query=ref(''),headers=ref('{}'),parameters=reactive({}),response=ref(null)
const keyForm=reactive({id:'',name:'',enabled:true,expires_at:'',permissions:[]})
const keyVisible=ref(false)
const visible=computed(()=>endpoints.value.filter(e=>(e.name+' '+e.path+' '+e.group).toLowerCase().includes(search.value.toLowerCase())))
const assignable=computed(()=>endpoints.value.filter(e=>e.auth==='admin'))
const groups=computed(()=>[...new Set(assignable.value.map(e=>e.group))])
const pathParams=computed(()=>selected.value?.path.match(/:[a-z_]+/g)||[])
const target=computed(()=>{let p=selected.value?.path||'';for(const key of pathParams.value)p=p.replace(key,encodeURIComponent(parameters[key.slice(1)]||''));return p+(query.value?'?'+query.value.replace(/^\?/, ''):'')})
function select(e){selected.value=e;body.value=JSON.stringify(e.request_example??{},null,2);query.value=e.path==='/api/check-link'?'provider=baidu':'';response.value=null;headers.value='{}';for(const k of Object.keys(parameters))delete parameters[k]}
async function refresh(){try{[endpoints.value,keys.value]=await Promise.all([props.api('/endpoints'),props.api('/api-keys')]);if(!selected.value)select(endpoints.value.find(x=>x.path==='/api/check-link')||endpoints.value[0])}catch(e){error.value=e.message}}
function editKey(k){Object.assign(keyForm,{id:k?.id||'',name:k?.name||'',enabled:k?.enabled??true,expires_at:k?.expires_at?new Date(k.expires_at).toISOString().slice(0,16):'',permissions:[...(k?.permissions||[])]});keyVisible.value=true;newToken.value=''}
function toggleGroup(group,event){const ids=assignable.value.filter(e=>e.group===group).map(e=>e.id);keyForm.permissions=event.target.checked?[...new Set([...keyForm.permissions,...ids])]:keyForm.permissions.filter(x=>!ids.includes(x))}
async function saveKey(){busy.value=true;error.value='';try{const data=await props.api('/api-keys'+(keyForm.id?'/'+keyForm.id:''),{method:keyForm.id?'PUT':'POST',body:JSON.stringify({name:keyForm.name,enabled:keyForm.enabled,expires_at:keyForm.expires_at?new Date(keyForm.expires_at+'Z').toISOString():null,permissions:keyForm.permissions})});newToken.value=data.api_key||'';notice.value='调用方权限已保存并立即生效。';keyVisible.value=false;await refresh()}catch(e){error.value=e.message}finally{busy.value=false}}
async function rotate(k){if(!confirm('轮换后旧Key立即失效。确认轮换？'))return;try{const d=await props.api('/api-keys/'+k.id+'/rotate',{method:'POST',body:'{}'});newToken.value=d.api_key;notice.value='新密钥仅本次展示，请保存到安全位置。'}catch(e){error.value=e.message}}
async function copy(text){try{await navigator.clipboard.writeText(text);notice.value='已复制'}catch{error.value='复制失败，请选中文本复制。'}}
function curl(){let h=selected.value.auth==='public'?'':" -H 'Authorization: Bearer <YOUR_KEY_OR_REPORT_TOKEN>'";let data=['GET','HEAD'].includes(selected.value.method)?'':" -H 'Content-Type: application/json' --data '<REQUEST_JSON>'";copy(`curl -X ${selected.value.method} '${location.origin}${target.value}'${h}${data}`)}
async function debug(){error.value='';response.value=null;if(pathParams.value.some(p=>!parameters[p.slice(1)])){error.value='请填写全部路径参数';return};const write=!['GET','HEAD'].includes(selected.value.method);if(write&&!confirm('这是真实写请求，会修改配置或凭证。确认执行？'))return;busy.value=true;try{const h=JSON.parse(headers.value);if(!h||typeof h!=='object'||Array.isArray(h))throw new Error('请求头必须是JSON对象');if(mode.value==='key'&&selected.value.auth!=='public'){if(!token.value)throw new Error('请填入调试凭证');h.Authorization='Bearer '+token.value}if(write){JSON.parse(body.value);h['Content-Type']='application/json'}const start=performance.now();const r=await fetch(target.value,{method:selected.value.method,headers:h,body:write?body.value:undefined,credentials:mode.value==='session'?'same-origin':'omit',cache:'no-store',redirect:'error'});response.value={status:r.status,duration_ms:Math.round(performance.now()-start),body:await r.text()}}catch(e){error.value=e.message}finally{busy.value=false}}
async function exportSpec(){try{const data=await props.api('/openapi');const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='seekbox-openapi.json';a.click();URL.revokeObjectURL(url)}catch(e){error.value=e.message}}
onMounted(refresh)
</script>
<template><section class="space-y-5">
<p class="status-error text-sm" v-if="error" role="alert">{{error}}</p><p class="status-ok text-sm" v-if="notice" role="status">{{notice}}</p>
<div v-if="newToken" class="rounded-xl border border-amber-200 bg-amber-50 p-5"><h3 class="text-sm font-semibold">新密钥 · 仅本次显示</h3><p class="my-3 break-all font-mono text-xs">{{newToken}}</p><button class="button-secondary" @click="copy(newToken)">复制密钥</button><button class="ml-3 text-xs" @click="newToken=''">已保存，隐藏</button></div>
<div class="panel p-5"><div class="flex flex-wrap items-center justify-between gap-3"><div><h3 class="font-semibold">调用方与 API Key</h3><p class="mt-1 text-xs text-slate-500">新Key默认无权限，勾选具体操作后生效。公开配置和实例上报保留各自鉴权。</p></div><button class="button-primary" @click="editKey(null)">新增调用方</button></div><div v-for="key in keys" :key="key.id" class="mt-4 flex flex-wrap items-center justify-between gap-3 border-t border-slate-100 pt-4"><div><p class="text-sm font-medium">{{key.name}} <span class="text-xs text-slate-400">{{key.enabled?'启用':'停用'}}</span></p><p class="mt-1 text-xs text-slate-400">{{key.permissions.length}} 项权限 · {{key.expires_at||'无到期时间'}}</p></div><div class="flex gap-3"><button class="text-sm text-blue-600" @click="editKey(key)">编辑授权</button><button class="text-sm text-blue-600" @click="rotate(key)">轮换</button></div></div><p v-if="!keys.length" class="py-5 text-sm text-slate-400">尚无调用方</p></div>
<form v-if="keyVisible" class="panel space-y-4 p-5" @submit.prevent="saveKey"><div class="grid gap-4 sm:grid-cols-3"><label><span class="field-label">调用方名称</span><input class="input" v-model="keyForm.name" required/></label><label><span class="field-label">有效期 · UTC，留空永久</span><input class="input" type="datetime-local" v-model="keyForm.expires_at"/></label><label class="flex items-center gap-2"><input type="checkbox" v-model="keyForm.enabled"/>启用此Key</label></div><div class="max-h-80 space-y-5 overflow-auto"><div v-for="group in groups"><label class="mb-3 flex items-center gap-2 text-sm font-semibold"><input type="checkbox" :checked="assignable.filter(e=>e.group===group).every(e=>keyForm.permissions.includes(e.id))" @change="toggleGroup(group,$event)"/>{{group}} · 选择当前已注册操作</label><label class="my-2 flex items-start gap-2 text-xs" v-for="e in assignable.filter(e=>e.group===group)"><input type="checkbox" :value="e.id" v-model="keyForm.permissions"/><span class="break-all">{{e.name}}<span class="ml-2 font-mono text-slate-400">{{e.id}}</span></span></label></div></div><p class="text-xs text-slate-400">勾选分组只授予当前清单，未来新增接口不会自动获得权限。</p><button class="button-primary" :disabled="busy">保存权限</button><button type="button" class="ml-4 text-sm" @click="keyVisible=false">取消</button></form>
<div class="flex flex-wrap items-center justify-between gap-3"><h3 class="font-semibold">接口文档与真实调试</h3><button class="button-secondary" @click="exportSpec">导出 OpenAPI</button></div>
<div class="grid items-start gap-5 lg:grid-cols-[300px_1fr]"><aside class="panel p-3"><input class="input mb-3" v-model="search" placeholder="搜索接口名称、路径、分组" aria-label="搜索接口"/><div class="max-h-80 overflow-y-auto lg:max-h-[700px]"><button v-for="e in visible" :key="e.id" class="block w-full rounded-lg p-3 text-left" :class="selected?.id===e.id?'bg-blue-50 text-blue-700':'hover:bg-slate-50'" @click="select(e)"><span class="text-xs font-semibold">{{e.name}}</span><span class="mt-1 block break-all font-mono text-[10px]">{{e.method}} {{e.path}}</span></button></div></aside>
<div v-if="selected" class="panel min-w-0 space-y-5 p-5"><div><span class="badge bg-blue-50 text-blue-700">{{selected.group}}</span><h4 class="mt-3 font-semibold">{{selected.name}}</h4><p class="mt-2 break-all font-mono text-xs">{{selected.method}} {{selected.path}}</p><p class="mt-3 text-xs leading-6 text-slate-500">{{selected.description}}</p><p class="mt-2 text-xs">鉴权：{{selected.auth}}</p></div>
<div v-if="selected.parameters?.length" class="overflow-x-auto"><table class="w-full text-left text-xs"><thead><tr><th class="p-2">字段 / 位置</th><th>必填</th><th>说明</th></tr></thead><tbody><tr v-for="p in selected.parameters" class="border-t"><td class="p-2 font-mono">{{p.name}}<small class="block">{{p.in}}</small></td><td>{{p.required?'是':'否'}}</td><td class="p-2">{{p.description}}</td></tr></tbody></table></div>
<details><summary class="cursor-pointer text-sm text-blue-600">响应结构说明与错误码</summary><pre class="mt-3 overflow-auto whitespace-pre-wrap break-all text-xs">{{JSON.stringify(selected.response_example,null,2)}}</pre><p class="mt-3 break-all text-xs">{{selected.errors.join(' · ')}}</p><button class="button-secondary mt-3" @click="copy(JSON.stringify(selected.response_example,null,2))">复制结构示例</button></details>
<div class="flex flex-wrap gap-3"><button class="button-secondary" @click="copy(location.origin+target)">复制地址</button><button class="button-secondary" @click="curl">复制 cURL</button><button class="button-secondary" @click="copy(body)">复制请求 JSON</button></div>
<div class="space-y-3 border-t pt-5"><label><span class="field-label">调试身份</span><select class="input" v-model="mode"><option value="key">指定 API Key / 实例上报凭证</option><option value="session">当前后台管理员会话</option></select></label><label v-if="mode==='key'&&selected.auth!=='public'"><span class="field-label">Bearer 凭证 · 仅保留在当前页面内存</span><input class="input" type="password" v-model="token" autocomplete="off" placeholder="输入对应凭证"/></label><label v-for="key in pathParams"><span class="field-label">路径参数 {{key.slice(1)}}</span><input class="input" v-model="parameters[key.slice(1)]" required/></label><label><span class="field-label">查询参数</span><input class="input" v-model="query" placeholder="provider=baidu"/></label><label><span class="field-label">请求头 JSON</span><textarea class="input font-mono" v-model="headers" rows="2"/></label><label v-if="selected.method!=='GET'"><span class="field-label">请求体 JSON</span><textarea class="input font-mono" v-model="body" rows="9"/></label><p class="text-xs text-slate-400">Key调试不发送后台Cookie，失败不会回退管理员身份。示例不是实际返回。</p><button class="button-primary" :disabled="busy" @click="debug">{{busy?'请求中…':'发送真实请求'}}</button></div>
<div v-if="response" class="rounded-lg bg-slate-950 p-4 text-slate-100"><p class="text-xs">HTTP {{response.status}} · {{response.duration_ms}} ms</p><pre class="mt-3 max-h-96 overflow-auto whitespace-pre-wrap break-all text-xs leading-5">{{response.body}}</pre></div>
</div></div>
</section></template>
